ccine', 'word', '523304c6-e440-581a-a772-4bfd821f05b6', 1, 'noun', 'en', 'vaccine', 'Vaccinen beskytter mod sygdommen.', 'The vaccine protects against the disease.'), ('eksplodere', 'word', '89e13187-09b0-561d-bff8-500e77f93cce', 1, 'verb', null, 'to explode', 'Bomben kan eksplodere når som helst.', 'The bomb can explode at any moment.'), ('ophæve', 'word', '6cb22218-f978-5056-b106-090e8a0e02c9', 1, 'verb', null, 'to repeal, to abolish (a law)', 'De vil ophæve loven.', 'They want to repeal the law.'), ('ophæve', 'word', 'eb21dc90-0de4-5808-8dcc-8dd7d05a6c2a', 2, 'verb', null, 'to annul, to cancel (an agreement)', 'Vi må ophæve aftalen.', 'We must cancel the agreement.'), ('single', 'word', 'dc2b8ab2-a1a1-54d0-8083-3bd562b1b652', 1, 'noun', 'en', 'single (unattached person)', 'Er du single?', 'Are you single?'), ('single', 'word', '0253687b-d34e-59dc-a468-54e30cb5ef7f', 2, 'noun', 'en', 'single (music track)', 'Bandet udgav en ny single.', 'The band released a new single.'), ('pande', 'word', 'cc9a1e1e-1918-5313-8799-23052cc5569b', 1, 'noun', 'en', 'frying pan', 'Steg kødet på en varm pande.', 'Fry the meat in a hot frying pan.'), ('pande', 'word', 'f50a961e-40db-5171-9a84-1f93fb8e3f50', 2, 'noun', 'en', 'forehead', 'Hun tørrede sveden af sin pande.', 'She wiped the sweat off her forehead.'), ('tyveri', 'word', '5f61a662-8a74-539f-b687-1196437f14b7', 1, 'noun', 'et', 'theft', 'Politiet efterforsker et tyveri.', 'The police are investigating a theft.'), ('kompromis', 'word', 'cef1dad6-8a14-555e-82f8-e067e1473b2d', 1, 'noun', 'et', 'compromise', 'De nåede frem til et kompromis.', 'They reached a compromise.'), ('væsen', 'word', '0ff31fc5-0908-51f9-9737-f6f0d7021e40', 1, 'noun', 'et', 'being, creature', 'Et levende væsen.', 'A living being.'), ('væsen', 'word', '16b72c32-206b-58a5-9745-37d0761a5fd6', 2, 'noun', 'et', 'nature, disposition', 'Hun har et mildt væsen.', 'She has a gentle nature.'), ('væsen', 'word', '8e9fe4b7-78d6-5301-80f6-2b5b18363704', 3, 'noun', 'et', 'system, sector (public administration)', 'Det offentlige væsen.', 'The public sector.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
